package com.xiaoxiaoshuo.reader;
import android.content.Context;import android.graphics.*;import android.graphics.drawable.BitmapDrawable;import android.widget.ImageView;import org.json.JSONObject;import java.io.*;import java.net.*;import java.security.MessageDigest;import java.util.*;import java.util.concurrent.*;
public final class CoverLoader{private static final ExecutorService POOL=Executors.newFixedThreadPool(4);private CoverLoader(){}public static void load(ImageView view,String raw,String base,String sourceJson,String title){if(view==null)return;view.setScaleType(ImageView.ScaleType.CENTER_CROP);view.setImageDrawable(new LiteraryCoverDrawable(title));String url=resolve(raw,base);if(url.length()==0)return;Context c=view.getContext().getApplicationContext();POOL.execute(()->{try{File dir=new File(c.getCacheDir(),"covers");dir.mkdirs();File f=new File(dir,hex(url)+".img");Bitmap bm=null;if(f.isFile()&&f.length()>128)bm=BitmapFactory.decodeFile(f.getAbsolutePath());if(bm==null){HttpURLConnection h=(HttpURLConnection)new URL(url).openConnection();h.setConnectTimeout(7000);h.setReadTimeout(9000);h.setInstanceFollowRedirects(true);h.setRequestProperty("User-Agent","Mozilla/5.0 (Linux; Android 12; Mobile) AppleWebKit/537.36 XiaoXiaoShuo/10.0");String referer=base;if(referer==null||referer.length()==0)referer=origin(url);if(referer.length()>0)h.setRequestProperty("Referer",referer);applyHeaders(h,sourceJson);InputStream in=h.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[16384];int n,total=0;while((n=in.read(buf))>0&&total<8*1024*1024){out.write(buf,0,n);total+=n;}in.close();byte[] data=out.toByteArray();bm=BitmapFactory.decodeByteArray(data,0,data.length);if(bm!=null){FileOutputStream fo=new FileOutputStream(f);fo.write(data);fo.close();}}final Bitmap ready=bm;if(ready!=null)view.post(()->{if(view.getWindowToken()!=null)view.setImageDrawable(new BitmapDrawable(view.getResources(),ready));});}catch(Throwable ignored){}});}private static void applyHeaders(HttpURLConnection h,String sourceJson){try{if(sourceJson==null||sourceJson.length()==0)return;JSONObject src=new JSONObject(sourceJson);Object x=src.opt("header");JSONObject o=null;if(x instanceof JSONObject)o=(JSONObject)x;else if(x instanceof String&&((String)x).trim().startsWith("{"))o=new JSONObject((String)x);if(o!=null){Iterator<String> it=o.keys();while(it.hasNext()){String k=it.next(),v=o.optString(k,"");if(v.length()>0)h.setRequestProperty(k,v);}}}catch(Throwable ignored){}}public static String resolve(String raw,String base){try{if(raw==null)return "";raw=raw.trim();if(raw.startsWith("//"))return "https:"+raw;if(raw.startsWith("http://")||raw.startsWith("https://"))return raw;if(base!=null&&base.length()>0)return new URL(new URL(base),raw).toString();}catch(Throwable ignored){}return "";}private static String origin(String s){try{URL u=new URL(s);return u.getProtocol()+"://"+u.getHost()+"/";}catch(Exception e){return "";}}private static String hex(String s){try{MessageDigest m=MessageDigest.getInstance("SHA-256");byte[] b=m.digest(s.getBytes("UTF-8"));StringBuilder x=new StringBuilder();for(byte q:b)x.append(String.format(Locale.US,"%02x",q));return x.toString();}catch(Exception e){return Integer.toHexString(s.hashCode());}}}